import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Grid, 
  Typography, 
  Box, 
  Tabs, 
  Tab, 
  CircularProgress,
  Button,
  Alert
} from '@mui/material';
import axios from 'axios';
import ContentCard from './ContentCard';
import MovieCarousel from './MovieCarousel';
import InfiniteScroll from 'react-infinite-scroll-component';

const Home = () => {
  const [activeTab, setActiveTab] = useState(0);
  const [trending, setTrending] = useState([]);
  const [popularMovies, setPopularMovies] = useState([]);
  const [popularTVShows, setPopularTVShows] = useState([]);
  const [topRatedMovies, setTopRatedMovies] = useState([]);
  const [topRatedTVShows, setTopRatedTVShows] = useState([]);
  const [upcomingMovies, setUpcomingMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);

  const fetchData = async (pageNum = 1, append = false) => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const config = {
        headers: {
          'x-auth-token': token
        }
      };

      const [
        trendingRes,
        popularMoviesRes,
        popularTVShowsRes,
        topRatedMoviesRes,
        topRatedTVShowsRes,
        upcomingMoviesRes
      ] = await Promise.all([
        axios.get('/api/movies/trending', config),
        axios.get(`/api/movies/popular/movie?page=${pageNum}`, config),
        axios.get(`/api/movies/popular/tv?page=${pageNum}`, config),
        axios.get(`/api/movies/top/movie?page=${pageNum}`, config),
        axios.get(`/api/movies/top/tv?page=${pageNum}`, config),
        axios.get(`/api/movies/upcoming?page=${pageNum}`, config)
      ]);

      if (append) {
        setPopularMovies(prev => [...prev, ...(popularMoviesRes.data.results || [])]);
        setPopularTVShows(prev => [...prev, ...(popularTVShowsRes.data.results || [])]);
        setTopRatedMovies(prev => [...prev, ...(topRatedMoviesRes.data.results || [])]);
        setTopRatedTVShows(prev => [...prev, ...(topRatedTVShowsRes.data.results || [])]);
        setUpcomingMovies(prev => [...prev, ...(upcomingMoviesRes.data.results || [])]);
      } else {
        setTrending(trendingRes.data);
        setPopularMovies(popularMoviesRes.data.results || []);
        setPopularTVShows(popularTVShowsRes.data.results || []);
        setTopRatedMovies(topRatedMoviesRes.data.results || []);
        setTopRatedTVShows(topRatedTVShowsRes.data.results || []);
        setUpcomingMovies(upcomingMoviesRes.data.results || []);
      }

      // Check if we've reached the end of available content
      setHasMore(
        popularMoviesRes.data.page < popularMoviesRes.data.total_pages &&
        popularTVShowsRes.data.page < popularTVShowsRes.data.total_pages &&
        topRatedMoviesRes.data.page < topRatedMoviesRes.data.total_pages &&
        topRatedTVShowsRes.data.page < topRatedTVShowsRes.data.total_pages &&
        upcomingMoviesRes.data.page < upcomingMoviesRes.data.total_pages
      );

      setError(null);
    } catch (err) {
      console.error('Error fetching data:', err);
      setError(err.response?.data?.msg || 'Error fetching data. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
    setPage(1);
    setHasMore(true);
  };

  const loadMore = () => {
    const nextPage = page + 1;
    setPage(nextPage);
    fetchData(nextPage, true);
  };

  const renderContent = (items, title) => (
    <InfiniteScroll
      dataLength={items.length}
      next={loadMore}
      hasMore={hasMore}
      loader={
        <Box display="flex" justifyContent="center" my={4}>
          <CircularProgress />
        </Box>
      }
      endMessage={
        <Box textAlign="center" my={4}>
          <Typography variant="body1" color="textSecondary">
            No more content to load
          </Typography>
        </Box>
      }
    >
      <Typography 
        variant="h4" 
        gutterBottom
        sx={{
          fontWeight: 'bold',
          textShadow: '2px 2px 4px rgba(0,0,0,0.2)',
          mb: 3,
        }}
      >
        {title}
      </Typography>
      <Grid container spacing={3}>
        {items.map((item) => (
          <Grid item xs={12} sm={6} md={4} lg={3} key={item.id}>
            <ContentCard content={item} />
          </Grid>
        ))}
      </Grid>
    </InfiniteScroll>
  );

  if (loading && page === 1) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="80vh">
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Container maxWidth="xl">
        <Box sx={{ mt: 4 }}>
          <Alert severity="error">{error}</Alert>
        </Box>
      </Container>
    );
  }

  return (
    <Container maxWidth="xl">
      {/* Movie Carousel */}
      {trending.length > 0 && (
        <Box sx={{ mt: 2 }}>
          <MovieCarousel movies={trending.slice(0, 5)} />
        </Box>
      )}

      <Box sx={{ 
        width: '100%', 
        mt: 4,
        '& .MuiTabs-root': {
          borderRadius: '20px',
          backgroundColor: 'rgba(255, 255, 255, 0.05)',
          padding: '10px',
          '& .MuiTab-root': {
            borderRadius: '15px',
            transition: 'all 0.3s ease',
            '&:hover': {
              backgroundColor: 'rgba(255, 255, 255, 0.1)',
            },
            '&.Mui-selected': {
              backgroundColor: 'rgba(255, 255, 255, 0.15)',
            },
          },
        },
      }}>
        <Tabs
          value={activeTab}
          onChange={handleTabChange}
          variant="scrollable"
          scrollButtons="auto"
          sx={{ 
            mb: 4,
            '& .MuiTabs-indicator': {
              borderRadius: '10px',
              height: '3px',
            },
          }}
        >
          <Tab label="Trending" />
          <Tab label="Popular Movies" />
          <Tab label="Popular TV Shows" />
          <Tab label="Top Rated Movies" />
          <Tab label="Top Rated TV Shows" />
          <Tab label="Upcoming Movies" />
        </Tabs>

        {activeTab === 0 && renderContent(trending, 'Trending Now')}
        {activeTab === 1 && renderContent(popularMovies, 'Popular Movies')}
        {activeTab === 2 && renderContent(popularTVShows, 'Popular TV Shows')}
        {activeTab === 3 && renderContent(topRatedMovies, 'Top Rated Movies')}
        {activeTab === 4 && renderContent(topRatedTVShows, 'Top Rated TV Shows')}
        {activeTab === 5 && renderContent(upcomingMovies, 'Upcoming Movies')}
      </Box>
    </Container>
  );
};

export default Home;
